EX = dict(id="nism-x-a", series="X-A", code="NISM Series X-A", short="Investment Adviser Level 1", title="Investment Adviser (Level 1)",
 track="nism-adv", tag="X-A", level="practitioner",
 blurb="The SEBI-mandated certification for investment advisers: markets, products, risk, planning, insurance, retirement, tax and ethics.",
 intro="NISM Series X-A is the first of the two certifications required by SEBI for registered investment advisers. It tests the product knowledge and the planning toolkit that an adviser uses with every client, with strong weight on insurance, retirement and tax.",
 who="Aspiring and existing SEBI-registered investment advisers, wealth managers, relationship managers, bank staff and anyone who wants to give holistic advice instead of selling single products.",
 qs=100, mins=120, **{"pass": 60}, pass_=60, neg="25% of marks", marks=100, days=35,
 glance=[["Format", "Computer-based, multiple-choice questions"], ["Questions and marks", "100 questions, 1 mark each, 100 marks"], ["Duration", "2 hours"], ["Passing score", "60 marks (60%)"], ["Negative marking", "25% of a question's marks, so 0.25 per wrong answer"], ["Certificate validity", "Three years; renew through NISM"], ["Where it leads", "SEBI investment adviser registration (with Level 2 where needed)"]],
 checklist=["Re-do time-value-of-money calculations: FV, PV, CAGR.", "Learn the SEBI IA fee caps and the segregation rule exactly.", "Revise the insurance types and the human life value idea.", "List retirement products with their lock-in and tax treatment.", "Take Mock 5 with negative marking switched on."],
 tips=["Negative marking applies. Eliminate options before guessing.", "For planning questions, name the client's goal and horizon first, then pick the product.", "Regulation questions use exact phrases such as 'fiduciary' and 'segregation'.", "Do not rely on interest rates from memory; questions test the type of instrument, not the rate.", "Keep a one-page list of formulas for FV, PV, CAGR and real return."],
 sheet=[("Formulas", [["Measure", "Formula"], ["Future value", "FV = PV × (1 + r)^n"], ["Present value", "PV = FV ÷ (1 + r)^n"], ["CAGR", "(End ÷ Start)^(1 ÷ n) − 1"], ["Real return (approx.)", "Nominal return − inflation"], ["Savings ratio", "Savings ÷ gross income"], ["Debt-service ratio", "EMIs ÷ monthly income"]])],
 units=[
 dict(n=1, title="Introduction to the Indian financial market", w=8,
  overview="The financial system, its institutions and regulators. Who regulates what, and how savings flow to investment.",
  focus=["Financial system components.", "Regulators: SEBI, RBI, IRDAI, PFRDA.", "Money, capital and forex markets."],
  visuals=[("table", "Who regulates what", [["Regulator", "Oversees"], ["RBI", "Banks, money market, forex, payment systems"], ["SEBI", "Securities markets, mutual funds, advisers"], ["IRDAI", "Insurance companies and intermediaries"], ["PFRDA", "NPS and pension funds"]], [150, 320])],
  facts=[("Financial system","The financial system consists of institutions, markets, instruments and regulators that move savings to productive uses.","Banks, markets and insurers together channel household savings into investments.","The financial system consists of banks only."),
   ("Financial market","A financial market is where financial assets are created and traded, and it is divided into money market, capital market and foreign exchange market.","Equity shares, short-term paper and currencies each trade in their own market.","Financial markets deal only in physical commodities."),
   ("RBI","The Reserve Bank of India is the central bank. It regulates banks, manages monetary policy and the money market, and issues currency.","The authority that sets the repo rate also regulates banks.","The RBI regulates mutual funds."),
   ("IRDAI","The Insurance Regulatory and Development Authority of India regulates insurers and intermediaries and protects policyholders.","A complaint about an insurance company's conduct is escalated to this body.","IRDAI regulates stock exchanges."),
   ("PFRDA","The Pension Fund Regulatory and Development Authority regulates the National Pension System and pension funds.","The body that oversees NPS fund managers and subscribers.","PFRDA regulates mutual funds."),
   ("Repo rate","The repo rate is the rate at which the RBI lends short-term funds to banks against government securities, and it is the main policy rate.","When the central bank raises the rate at which banks borrow, loan rates tend to rise.","A repo rate cut makes loans costlier."),
   ("Inflation and interest rates","When inflation rises, central banks tend to raise rates to cool demand, which affects bond prices and borrowing costs.","Rising prices lead to higher policy rates and lower bond prices.","High inflation always leads to lower interest rates."),
   ("Primary dealer","Primary dealers are institutions that underwrite and trade government securities and support the central bank in managing borrowing.","An institution that bids at government auctions and makes a market in G-secs.","Primary dealers sell only equity shares."),
   ("Stock exchanges and depositories","Exchanges provide the trading platform; depositories hold securities in electronic form; clearing corporations settle trades.","A trade flows through an exchange, a clearing corporation and a depository.","Depositories execute trades on exchanges."),
   ("Foreign portfolio investor","A foreign portfolio investor is an overseas entity that invests in Indian securities, registered under SEBI's regulations.","An overseas fund buys listed Indian shares and bonds.","An FPI is an Indian retail investor."),
   ("Credit rating agency","A credit rating agency assesses the creditworthiness of issuers and their debt instruments and is regulated by SEBI.","An independent agency rates a company's bonds as AA+.","A credit rating agency issues the bonds."),
   ("Money supply and liquidity","Liquidity in the system is influenced by the RBI's tools such as CRR, SLR and open market operations.","The central bank buys securities to inject liquidity into the system.","Liquidity is controlled only by the stock exchanges.")]),
 dict(n=2, title="Securities market segments", w=10,
  overview="Equity, debt and derivative segments, how they work and what a client is buying when she buys each.",
  focus=["Equity market and its participants.", "Debt market: G-secs, corporate bonds, money market.", "Derivatives for advisers."],
  facts=[("Equity market","The equity market is where shares are issued and traded, giving investors ownership and a claim on residual profits.","An investor buys shares and shares in a company's future profit.","The equity market offers fixed returns."),
   ("Debt market","The debt market is where fixed-income securities such as bonds and treasury bills are issued and traded.","An investor lends to a government in return for interest.","The debt market gives investors ownership of companies."),
   ("Primary and secondary markets","The primary market creates new securities and the secondary market trades existing ones, giving liquidity to investors.","An IPO happens in the primary market; later trading happens in the secondary market.","Trading among investors takes place in the primary market."),
   ("Demat and trading accounts","A demat account holds securities electronically and a trading account is used to place orders through a broker.","An investor needs both to buy shares on an exchange.","A demat account is used to place orders."),
   ("Settlement cycle","Equity cash market trades settle on T+1, meaning the next working day after the trade.","A share bought on Monday is settled the next working day.","Equity trades take a week to settle."),
   ("Corporate bond market","Corporate bonds are debt securities issued by companies and carry credit risk, rated by rating agencies.","A company raises money by issuing rated bonds.","Corporate bonds are free from credit risk."),
   ("Government securities market","G-secs are issued by the government to borrow, and carry virtually no credit risk, though prices move with interest rates.","A government bond has no default risk but its price can fall when rates rise.","G-sec prices never change."),
   ("Money market instruments","Money market instruments mature within a year and include T-bills, CP, CD and repos.","A company parks funds for 60 days in a short-term instrument.","Money market instruments mature after ten years."),
   ("Derivatives for advisers","Derivatives such as futures and options are used for hedging and speculation; advisers must understand leverage before recommending them.","An adviser explains why a protective position may reduce a client's portfolio risk.","Derivatives remove market risk entirely."),
   ("Stock market indices","Indices such as the Sensex and Nifty 50 track the market and are benchmarks for portfolios and index funds.","A portfolio manager compares returns with a broad market index.","Indices are fixed numbers that never change."),
   ("Short-term vs long-term capital gains","Gains on listed shares and equity funds are short-term if held up to 12 months and long-term if held longer, with different tax rates.","An investor selling after 15 months realises a long-term gain.","The tax rate is the same regardless of the holding period."),
   ("Market risk of equity","Equity prices fluctuate with company performance and market sentiment, and capital can be lost, especially over short horizons.","A client's equity fund falls 15% in a quarter.","Equities cannot lose value over short periods."),
   ("Settlement guarantee","The clearing corporation guarantees the settlement of exchange trades, reducing counterparty risk for investors.","A trader need not worry that the other party will fail to deliver.","Exchange trades have no settlement guarantee."),
   ("Rating scales","Bond ratings range from the highest (AAA) to default (D), and investment grade is generally BBB- and above.","A bond rated BB is considered below investment grade.","BBB is the highest rating."),
   ("Yield curve","The yield curve plots yields of bonds against their maturities; an upward-sloping curve is normal, where longer maturities yield more.","Ten-year bonds yield more than one-year bonds.","The yield curve plots share prices against time."),
   ("Liquidity of securities","Liquidity varies by security: large-cap shares and G-secs trade easily while thinly traded bonds can be hard to sell.","A client finds it difficult to sell a thinly traded bond.","All securities are equally liquid.")]),
 dict(n=3, title="Mutual funds", w=9,
  overview="Funds from an adviser's viewpoint: structure, categories, costs, taxation and how to compare schemes.",
  focus=["Scheme categories and fit.", "Direct versus regular plans.", "Taxation of funds."],
  facts=[("Mutual fund structure","A mutual fund has a sponsor, trust, trustees and an AMC, supported by a custodian and RTA, and is regulated by SEBI.","A three-tier structure oversees the investor's money.","A mutual fund is a bank deposit."),
   ("Direct plan for advisers","A registered investment adviser charging a fee should generally recommend direct plans to avoid receiving commissions.","An adviser who charges a fee puts the client into the lower-cost plan.","An adviser charging a fee can also collect trail commission from the same client."),
   ("NAV","NAV is the per-unit value of a scheme, equal to total assets less liabilities divided by units outstanding.","A scheme with ₹100 crore net assets and 5 crore units has a NAV of ₹20.","NAV is the price paid for shares on the exchange."),
   ("Equity fund categories","SEBI defines categories such as large cap, mid cap, small cap, flexi cap and ELSS, each with minimum equity allocations.","A scheme must keep at least 80% in top-100 stocks to be called a large cap fund.","A large cap fund can hold any mix of stocks."),
   ("Debt fund risk","Debt funds are exposed to interest-rate risk, credit risk and liquidity risk, and returns are not guaranteed.","A bond fund loses value when interest rates rise.","Debt funds are free of risk."),
   ("Hybrid funds","Hybrid funds combine equity and debt, with varied allocations, to balance growth and stability.","A client wanting moderate risk holds a scheme with 65% equity and 35% debt.","Hybrid funds invest only in debt."),
   ("Expense ratio","The expense ratio is the annual charge as a percentage of a scheme's assets and reduces the investor's return.","A scheme charging 1.5% costs the investor ₹1,500 yearly on ₹1 lakh.","The expense ratio is charged only at entry."),
   ("Exit load","Exit load is charged on redemption within a defined period and is credited to the scheme.","A fund levies 1% if units are sold within a year.","Exit load is a commission paid to the adviser."),
   ("SIP","A Systematic Investment Plan invests a fixed sum at regular intervals and helps to average the purchase cost over time.","A client invests ₹10,000 monthly in a fund.","A SIP assures positive returns."),
   ("Riskometer","The riskometer shows a scheme's risk on six levels from low to very high, and should match the client's risk profile.","An adviser compares the scheme's risk label with the client's tolerance.","Riskometer shows the scheme's past return."),
   ("Tax on mutual funds","Equity-oriented funds are taxed on short- and long-term gains at different rates, while specified debt funds are taxed at the investor's slab rate.","A debt fund gain is added to the investor's total income.","All mutual fund gains are tax-free."),
   ("Fund selection","An adviser compares funds on risk-adjusted return, consistency, costs, portfolio quality and fit with the client's goals, not just recent performance.","An adviser reviews five-year rolling returns, not just last year.","The previous year's best fund is always the right choice."),
   ("ETF and index funds","ETFs and index funds replicate an index at low cost; ETFs trade on exchanges while index funds are bought from the AMC.","A client buys a low-cost fund that mirrors the Nifty 50.","ETFs are bought only through the AMC at NAV."),
   ("Portfolio overlap","Holding several funds with similar portfolios increases overlap and reduces diversification benefits.","A client owns five large-cap funds with the same top holdings.","More funds always mean better diversification.")]),
 dict(n=4, title="Investment products", w=12,
  overview="The shelf of products an adviser can use: deposits, small savings, bonds, equity, gold, real estate, REITs, PMS, AIFs and structured products.",
  focus=["Features, risk, return, liquidity and tax of each product.", "Which product suits which goal."],
  visuals=[("table", "Product comparison", [["Product", "Risk", "Liquidity", "Typical role"], ["Bank FD", "Low", "Moderate", "Capital safety"], ["PPF", "Government-backed", "Low", "Long-term safe, tax-efficient"], ["Equity", "High", "High", "Growth"], ["Gold", "Moderate", "High", "Hedge"], ["Real estate", "Moderate to high", "Low", "Long-term, income"], ["REIT/InvIT", "Moderate", "High (listed)", "Income"]], [110, 110, 110, 140])],
  facts=[("Fixed deposit","A fixed deposit gives a fixed return for a fixed period, with capital safety up to the deposit insurance limit and interest taxable at slab rates.","A saver locks a sum for three years at a known rate.","A fixed deposit gives market-linked returns."),
   ("Deposit insurance","Deposit insurance covers bank deposits up to ₹5 lakh per depositor per bank in case of bank failure.","A depositor holds ₹8 lakh in one bank, with ₹5 lakh insured.","All deposits of any amount are fully insured."),
   ("Public Provident Fund","PPF is a government-backed small savings scheme with a 15-year tenure, tax benefits on deposit and interest, and limited premature withdrawal.","A long-term saver builds a tax-efficient corpus over fifteen years.","PPF can be fully withdrawn after one year."),
   ("Sukanya Samriddhi Yojana","The Sukanya Samriddhi account is a small savings scheme for the girl child with tax benefits and a long lock-in until maturity or marriage after 18.","A parent opens an account for her daughter's education and marriage.","Sukanya Samriddhi is available for any child."),
   ("Senior Citizens' Savings Scheme","SCSS is a government-backed scheme for those aged 60 and above with a five-year tenure, offering regular interest payouts.","A retiree places a lump sum for regular quarterly income.","SCSS is open to any age."),
   ("Sovereign gold bond","A sovereign gold bond is a government security denominated in grams of gold that pays interest and has no storage or purity issues, with a defined tenure.","An investor holds gold on paper, backed by the government, and earns annual interest.","A sovereign gold bond pays no interest."),
   ("Gold ETF","A gold ETF is a fund that holds physical gold and trades on an exchange, giving gold exposure without storage.","An investor buys units of gold in a demat account.","A gold ETF offers jewellery on redemption."),
   ("Equity share","An equity share offers ownership and growth potential, dividends and voting rights, but with the highest risk among common products.","A client wants long-term growth and can bear volatility.","Equity gives assured returns."),
   ("REIT","A REIT owns and operates income-producing real estate and distributes most of its income to unit holders, listed on exchanges.","An investor holds units in a trust that owns office buildings.","A REIT invests in debt instruments of companies."),
   ("InvIT","An InvIT pools money to invest in infrastructure assets such as roads and power lines and distributes income to unit holders.","An investor buys units in a trust that owns toll roads.","An InvIT invests only in residential flats."),
   ("Real estate","Real estate offers appreciation and rental income but is illiquid, high in ticket size and costly to transact.","A client finds it hard to sell a property quickly.","Real estate is a liquid investment."),
   ("PMS","Portfolio management services manage a client's portfolio of securities in a segregated account, with a minimum investment of ₹50 lakh.","A wealthy client hands over a securities portfolio to a professional manager.","PMS has no minimum investment."),
   ("Alternative investment fund","An AIF is a privately pooled fund investing in non-traditional assets and strategies, with a minimum investment of ₹1 crore.","An investor puts ₹1 crore into a private equity fund.","An AIF accepts investments of ₹10,000."),
   ("Structured product","A structured product combines a debt instrument with a derivative to deliver a customised payoff, and may carry high complexity and issuer risk.","A product offers returns linked to an index with partial capital protection.","Structured products are simple and risk free."),
   ("NPS as a product","NPS is a defined-contribution pension scheme invested in equity, corporate bonds and government securities, with a partly mandatory annuity at exit.","A person builds a retirement corpus with regulated pension fund managers.","NPS is a mutual fund."),
   ("Bonds and debentures","Bonds are debt instruments paying interest and returning principal at maturity; yields depend on credit quality and tenure.","A client receives coupons and principal on a corporate bond.","Bond returns are linked to company profits."),
   ("Annuity","An annuity is a series of regular payments, usually from an insurer, bought with a lump sum, to provide income in retirement.","A retiree pays a lump sum and receives monthly income for life.","An annuity pays a single lump sum at maturity."),
   ("Unit linked insurance plan","A ULIP combines insurance with market-linked investment, with charges for mortality, administration and fund management.","A policy invests part of the premium in funds and part in cover.","A ULIP has no charges."),
   ("Corporate fixed deposit","A corporate fixed deposit is a deposit with a company at a higher rate than banks, with higher risk and no deposit insurance.","A client considers a company deposit for its higher interest.","Company deposits are insured like bank deposits."),
   ("Recurring deposit","A recurring deposit lets a saver deposit a fixed sum every month for a fixed term, earning a fixed interest rate.","A saver puts ₹5,000 monthly into a bank for two years.","A recurring deposit needs a single lump sum at the start.")]),
 dict(n=5, title="Managing investment risk", w=7,
  overview="Risk is more than volatility. This unit lists the types of risk and the tools to measure and manage them.",
  focus=["Types of risk.", "Standard deviation and beta.", "Diversification and risk management steps."],
  facts=[("Market risk","Market risk is the risk of loss from overall movements in market prices that cannot be diversified away.","A portfolio falls because the whole market fell.","Market risk can be eliminated by diversification."),
   ("Credit risk","Credit risk is the chance that a borrower will not repay interest or principal on time.","A bond issuer defaults on interest payments.","Credit risk applies only to equity shares."),
   ("Interest rate risk","Interest rate risk is the risk that changes in interest rates will affect the value of fixed-income investments; prices fall when rates rise.","A bond portfolio loses value after the policy rate is raised.","Bond prices rise when interest rates rise."),
   ("Inflation risk","Inflation risk is the risk that returns will not keep pace with price rises, eroding purchasing power.","A saver's 5% deposit returns less than the 6% inflation.","Inflation risk affects only equity investors."),
   ("Liquidity risk","Liquidity risk is the risk of being unable to sell an asset quickly at a fair price.","A client cannot sell a plot of land at short notice.","Liquidity risk is the chance of a price fall."),
   ("Reinvestment risk","Reinvestment risk is the risk that cash flows such as coupons can only be reinvested at lower rates than the original.","A bond's coupons are reinvested at lower rates after rates fall.","Reinvestment risk is the risk of default."),
   ("Systematic and unsystematic risk","Systematic risk affects the whole market and cannot be diversified; unsystematic risk is specific to a company or sector and can be reduced by diversification.","A strike at one company is specific risk, while a recession affects all.","Systematic risk can be diversified away."),
   ("Standard deviation","Standard deviation measures how widely returns vary around the average and is used as a measure of total risk.","A fund with a standard deviation of 20% is more volatile than one with 10%.","A higher standard deviation indicates lower risk."),
   ("Beta","Beta measures a security's sensitivity to market moves; beta above 1 means more volatile than the market.","A stock with a beta of 1.4 tends to move more than the market.","A beta of 1 means the stock never moves."),
   ("Diversification","Diversification reduces unsystematic risk by holding assets that do not move together, such as equity, debt and gold.","An investor spreads money across asset classes and sectors.","Diversification eliminates all risk."),
   ("Risk tolerance","Risk tolerance is a client's willingness to accept fluctuations; it differs from risk capacity, which is the ability to bear loss.","A client who loses sleep over a small fall has low tolerance.","Risk tolerance is a fixed number set by regulation."),
   ("Risk management process","Risk management involves identifying risks, measuring them, choosing a treatment such as avoiding, reducing, transferring or retaining and monitoring.","A family buys health insurance to transfer the risk of a large medical bill.","Risk management means ignoring all risks."),
   ("Value at Risk","Value at Risk estimates the maximum likely loss over a period at a given confidence level under normal conditions.","A portfolio's one-day 95% VaR is ₹2 lakh.","VaR is the worst possible loss ever."),
   ("Risk-adjusted return","Risk-adjusted measures such as the Sharpe ratio show return earned per unit of risk taken.","Two funds with equal returns are compared on how much risk each took.","The highest-return fund always has the best risk-adjusted performance.")]),
 dict(n=6, title="Measuring investment returns", w=7,
  overview="Formulas matter here: holding period return, CAGR, IRR, real return and the effect of tax and costs.",
  focus=["Absolute and annualised return.", "IRR and XIRR.", "Real and post-tax return."],
  visuals=[("formula", "CAGR", "CAGR = (Ending value ÷ Beginning value)^(1 ÷ years) − 1"), ("formula", "Future value", "FV = PV × (1 + r)^n")],
  facts=[("Holding period return","Holding period return is the total return over the period an investment is held, including income and price change, as a percentage of the initial value.","An investment of ₹100 returns ₹115 including dividends.","Holding period return is the annual yield."),
   ("CAGR","CAGR is the constant annual rate at which an investment grows over a period longer than a year, assuming compounding.","₹1 lakh becomes ₹1.44 lakh in three years, about 13% a year.","CAGR is the simple average of yearly returns."),
   ("IRR","The internal rate of return is the rate that makes the present value of cash inflows equal to the outflows, used for irregular cash flows.","A series of deposits and withdrawals is summarised in one annual rate.","IRR ignores the timing of cash flows."),
   ("XIRR","XIRR computes the annualised return for investments made on specific dates, such as monthly SIPs.","An adviser wants the true return on a three-year SIP.","XIRR cannot be used for SIPs."),
   ("Real return","Real return is nominal return adjusted for inflation; it shows the growth in purchasing power.","A 9% return with 6% inflation gives about 3% in real terms.","Real return equals nominal return."),
   ("Post-tax return","Post-tax return is the return after deducting tax, and is the figure that matters to the client.","An investor compares products after tax.","Pre-tax return is the final return."),
   ("Time value of money","Money available now is worth more than the same amount in the future, because it can be invested to earn a return.","₹1 lakh today beats ₹1 lakh received in five years.","A rupee today and tomorrow are equal."),
   ("Present value","Present value is the current worth of a future sum, discounted at a given rate.","₹1.1 lakh receivable in a year at 10% is worth ₹1 lakh today.","Present value is always more than future value."),
   ("Future value","Future value is the amount an investment will grow to after earning a given return over a period.","₹1 lakh at 10% for two years grows to ₹1.21 lakh.","Future value is the value today of future cash flow."),
   ("Annuity versus perpetuity","An annuity pays a fixed amount for a fixed number of periods, while a perpetuity pays forever.","A pension that continues for life with no end date is like a perpetuity.","A perpetuity stops after ten years."),
   ("Rule of 72","The Rule of 72 estimates the years for money to double by dividing 72 by the annual return in percent.","At 8% an investment doubles in about nine years.","The Rule of 72 gives the tax payable."),
   ("Impact of costs","Fees and expense ratios reduce net returns, and the effect compounds over long periods.","A 1% yearly cost on a 12% return reduces ending wealth materially over twenty years.","Costs have no effect on long-term returns."),
   ("Benchmarking","Comparing a portfolio's return with a relevant benchmark shows whether the manager added value after adjusting for risk.","A fund's return is compared with its category index.","Any index can be used as a benchmark for any fund."),
   ("Time-weighted versus money-weighted","Time-weighted return removes the effect of cash flows, judging a manager; money-weighted return, like IRR, reflects the investor's own timing of flows.","A manager's skill is judged ignoring the investor's deposits and withdrawals.","Both measures are always the same.")]),
 dict(n=7, title="Concept of financial planning", w=4,
  overview="The planning process, from understanding the client to monitoring.",
  focus=["Six steps of financial planning.", "Life-cycle needs.", "Balance sheet and cash flow."],
  visuals=[("flow", "Financial planning process", ["Establish relationship", "Gather data and goals", "Analyse position", "Recommend plan", "Implement", "Monitor and review"])],
  facts=[("Financial planning process","The process involves establishing the client relationship, gathering information, analysing, recommending, implementing and monitoring.","An adviser starts by agreeing scope and fees before collecting data.","Financial planning starts with product recommendation."),
   ("Fiduciary duty","An adviser acts as a fiduciary, putting the client's interests ahead of her own and avoiding conflicts of interest.","An adviser recommends a lower-cost option though it pays her less.","A fiduciary may put her own interest first."),
   ("Net worth statement","A net worth statement lists assets and liabilities; net worth equals assets minus liabilities.","A client's assets are ₹80 lakh and liabilities ₹30 lakh, giving ₹50 lakh.","Net worth is total income minus expenses."),
   ("Cash flow statement","A cash flow statement lists a client's income and expenses to show the surplus available for saving.","An adviser reviews monthly inflows and outflows to find the surplus.","A cash flow statement lists assets only."),
   ("Financial ratios","Ratios such as savings ratio, liquidity ratio and debt-service ratio show the client's financial health.","An adviser checks whether EMIs exceed 40% of income.","Financial ratios are used only for companies."),
   ("Goal prioritisation","Goals are ranked by importance and urgency, such as emergency fund, protection, education and retirement, so funds go where they matter most.","A client funds insurance and emergency money before a car purchase.","All goals are funded equally without ranking."),
   ("Life-cycle planning","Financial needs and risk capacity change through life stages such as starting work, family building, peak earning and retirement.","A young single client can usually take more equity risk than a retiree.","Life stage does not affect planning."),
   ("Emergency fund","An emergency fund is three to six months of expenses held in liquid, safe assets.","A client sets aside funds in a liquid fund for emergencies.","An emergency fund is invested in small-cap equity."),
   ("Financial plan review","A plan should be reviewed at least annually and whenever there is a major life event such as marriage, a child or job change.","A client's plan is updated after the birth of a child.","A plan once made is never revisited."),
   ("Planning scope","A comprehensive plan covers cash flow, risk management, investments, tax, retirement and estate planning.","An adviser looks at all aspects of a client's finances.","Financial planning is only about investments.")]),
 dict(n=8, title="Asset allocation and investment strategies", w=5,
  overview="Asset allocation drives the majority of long-run portfolio outcomes. Strategies for implementing it.",
  focus=["Strategic and tactical allocation.", "Rebalancing.", "Active versus passive."],
  facts=[("Strategic asset allocation","Strategic allocation sets long-term target weights across asset classes based on goals and risk profile, with periodic rebalancing.","A client's plan fixes 60% equity and 40% debt for years.","Strategic allocation changes with every market move."),
   ("Tactical asset allocation","Tactical allocation makes short-term shifts away from strategic weights to exploit perceived opportunities.","An adviser temporarily reduces equity because valuations look stretched.","Tactical allocation is never allowed."),
   ("Rebalancing","Rebalancing restores the target allocation by selling what has grown overweight and buying what lags, controlling risk.","Equity rises to 70% of a 60% target, so some is sold.","Rebalancing means buying only winners."),
   ("Core and satellite","A core and satellite approach keeps most assets in low-cost diversified holdings and a smaller part in higher-conviction ideas.","A client holds 75% in index funds and 25% in thematic funds.","The satellite is the main holding."),
   ("Active versus passive investing","Active investing tries to beat a benchmark through selection; passive investing tracks it at low cost.","An index fund follows the market rather than trying to beat it.","Active funds always beat passive funds."),
   ("Lump sum versus SIP","Lump sum investing puts money in at once while SIP spreads entry over time to average the cost and reduce timing risk.","A client with a bonus splits it into monthly instalments.","A SIP always beats a lump sum."),
   ("Glide path","A glide path gradually moves a portfolio from growth assets to safer assets as a goal date approaches.","As retirement nears, equity share is steadily lowered.","A glide path raises equity near the goal."),
   ("Investment policy statement","An investment policy statement documents the client's objectives, constraints, allocation and review rules, guiding long-term discipline.","An adviser and client sign a document setting out targets and limits.","An investment policy statement is a promise of returns."),
   ("Behavioural biases","Biases such as overconfidence, loss aversion and herding lead investors to make poor decisions; advisers help counter them.","A client sells in panic after a fall.","Investors always behave rationally.")]),
 dict(n=9, title="Insurance planning", w=10,
  overview="Insurance protects the plan. This unit covers life and health insurance, need analysis, types of policies and claims.",
  focus=["Term versus savings policies.", "Human life value and need-based cover.", "Health and general insurance."],
  visuals=[("flow", "Insurance needs analysis", ["List liabilities", "Estimate future needs", "Add family goals", "Subtract assets", "Gap = cover needed"])],
  facts=[("Term insurance","Term insurance pays the sum assured on death during the term and nothing on survival, making it the cheapest pure protection.","A family earner buys cover for twenty years at a low premium.","Term insurance returns premiums if the policyholder survives."),
   ("Endowment plan","An endowment plan combines life cover with savings and pays on maturity or earlier death, with lower cover and returns than term plus investment.","A policy pays a lump sum after twenty years or on earlier death.","An endowment plan offers the highest cover per rupee."),
   ("Whole life insurance","Whole life insurance provides cover for the whole life of the insured, typically up to a very advanced age.","A policy that pays at death whenever it occurs.","Whole life insurance ends at 60."),
   ("Human life value","Human life value estimates the present value of the future income of a person that his family would lose on his death.","An adviser computes the value of future earnings to size the cover.","Human life value is the sum of premiums paid."),
   ("Needs analysis","Needs analysis sizes life cover by adding liabilities and future goals and subtracting existing assets.","An adviser adds a home loan and child education costs and subtracts savings.","Cover is fixed at five times the premium."),
   ("Rider","A rider is an optional benefit added to a base policy for an extra premium, such as accidental death or critical illness.","A policyholder adds a benefit that pays on diagnosis of a serious disease.","A rider reduces the base premium."),
   ("Health insurance","Health insurance covers hospitalisation and related costs up to the sum insured; features include waiting periods, co-payment and exclusions.","A policy pays ₹5 lakh of hospital costs in a year.","Health insurance pays unlimited costs."),
   ("Family floater","A family floater covers the whole family under one sum insured shared among members.","A couple and children share one ₹10 lakh cover.","A floater gives each member a separate sum insured."),
   ("Super top-up","A super top-up pays when claims in a year exceed a threshold, giving high cover at a low premium.","A client adds ₹50 lakh cover above a ₹10 lakh deductible.","A super top-up replaces the base policy."),
   ("Waiting period","A waiting period is the time after purchase during which certain claims, such as pre-existing diseases, are not payable.","A claim for a planned surgery is rejected in the first month.","Waiting periods do not exist in health policies."),
   ("Critical illness cover","Critical illness cover pays a lump sum on diagnosis of specified serious illnesses, regardless of actual expenses.","A policy pays ₹20 lakh on diagnosis of cancer.","Critical illness cover reimburses bills only."),
   ("Personal accident cover","Personal accident insurance pays on death or disability caused by accident, and may pay for temporary disablement.","A policy pays when the insured loses a limb in an accident.","Personal accident cover pays for any illness."),
   ("Motor insurance","Third-party motor insurance is mandatory in India and covers liability to others; comprehensive cover also covers damage to own vehicle.","An owner buys a policy covering both liability and own damage.","Third-party cover pays for damage to your own car."),
   ("Home insurance","Home insurance covers loss or damage to the structure and contents from specified perils such as fire and flood.","A homeowner insures the building against fire.","Home insurance covers only jewellery."),
   ("Insured versus assured","Under insurance, indemnity policies compensate actual loss up to the sum insured, while life policies pay a fixed sum assured.","Health policy reimburses actual bills; life policy pays the fixed sum.","Life insurance reimburses actual loss."),
   ("Claim settlement ratio","The claim settlement ratio shows the share of claims paid by an insurer; a high ratio suggests a better claim record.","An insurer paid 98 of every 100 claims.","Claim ratio is the premium refunded."),
   ("Nomination and assignment","A nominee receives the policy proceeds on the insured's death, while assignment transfers rights in the policy to another person, such as a lender.","A policyholder names his wife to receive the claim.","A nominee becomes the permanent owner of the policy."),
   ("Underwriting","Underwriting is the insurer's process of assessing risk and deciding whether to accept a proposal and at what premium.","An insurer asks for medical tests before issuing a large cover.","Underwriting is the payment of claims."),
   ("Free-look period","The free-look period lets a policyholder return a policy within a stated number of days and get a refund of premium, less minor deductions.","A buyer cancels the policy within the free-look window.","The free-look period starts after the first claim."),
   ("Mis-selling in insurance","Selling insurance as an investment, or hiding charges and conditions, is mis-selling and a conduct violation.","An agent promises that a policy will double money in five years.","Selling insurance as a guaranteed investment is acceptable.")]),
 dict(n=10, title="Retirement planning", w=10,
  overview="Estimating the corpus, choosing products and planning withdrawals. Retirement is a multi-decade project with inflation as the main enemy.",
  focus=["Corpus estimation.", "EPF, PPF, NPS and annuities.", "Withdrawal strategies."],
  visuals=[("flow", "Retirement planning steps", ["Estimate expenses", "Adjust for inflation", "Compute corpus", "Choose products", "Invest and review", "Plan withdrawals"])],
  facts=[("Retirement corpus","The retirement corpus is the accumulated sum needed to fund expenses after retirement, estimated using expenses, inflation, years in retirement and returns.","A client works out the lump sum she needs at 60.","The corpus is the amount spent each month."),
   ("Replacement ratio","The replacement ratio is the percentage of pre-retirement income needed after retirement to maintain the lifestyle, often taken as 60% to 80%.","A client needs 70% of her final income in retirement.","The replacement ratio is more than 100% for everyone."),
   ("Longevity risk","Longevity risk is the risk of outliving one's savings because life expectancy is increasing.","A retiree is still alive when savings run out.","Longevity risk is the risk of dying early."),
   ("Employees' Provident Fund","The EPF is a mandatory retirement savings scheme for salaried employees with contributions from employee and employer, and interest declared annually.","A salaried person's monthly contribution is matched by her employer.","EPF is voluntary for all employees."),
   ("National Pension System","NPS is a voluntary defined-contribution scheme in which contributions are invested in equity, corporate bonds and government securities, with a part of the corpus used for an annuity.","A person builds her pension through a regulated portable account.","NPS guarantees a fixed pension."),
   ("NPS Tier I and Tier II","Tier I is the retirement account with restricted withdrawals, while Tier II is a voluntary savings account with free withdrawals.","A subscriber keeps a flexible withdrawal account in addition to the main account.","Tier I allows free withdrawal at any time."),
   ("Annuity options","Annuity options include life annuity, annuity with return of purchase price and joint-life annuity, each differing in payout and continuation.","A couple selects an annuity that continues for the spouse after the first death.","All annuities pay the same."),
   ("Systematic withdrawal plan","A systematic withdrawal plan redeems a fixed amount from a fund at regular intervals to create retirement income.","A retiree draws a monthly sum from a debt fund.","An SWP buys more units every month."),
   ("Safe withdrawal rate","A safe withdrawal rate is the percentage of the corpus that can be withdrawn each year with a low chance of running out, commonly assumed at around 4% in global studies.","A client withdraws a modest percentage each year to make a corpus last.","A safe withdrawal rate is the rate of inflation."),
   ("Inflation in retirement","Inflation raises expenses over a long retirement, so some growth assets are needed even after retirement.","A retiree's monthly cost of ₹50,000 rises over twenty years.","Retirees should avoid all growth assets."),
   ("Bucket strategy","A bucket strategy divides retirement money into near-term cash, medium-term income and long-term growth buckets.","A retiree holds two years of expenses in cash and the rest invested for growth.","The bucket strategy puts everything in one asset."),
   ("Medical costs in retirement","Healthcare costs usually rise faster than general inflation, so retirement planning should include adequate health insurance.","A retiree faces large medical expenses at 75.","Medical costs fall after retirement."),
   ("Pension from employer","A defined-benefit pension promises a fixed pension based on salary and service, while defined-contribution plans depend on contributions and returns.","A government employee receives a pension formula-based on last salary.","In a defined-contribution plan the pension is guaranteed."),
   ("Reverse mortgage","A reverse mortgage lets senior citizens convert home equity into regular income while staying in the home, with the loan repaid from sale of the house later.","A senior receives monthly payments against her house, and keeps living there.","A reverse mortgage requires moving out immediately."),
   ("Start early advantage","Starting early gives compounding more time, so a smaller monthly investment can build a larger corpus than a later start with a bigger sum.","A 25-year-old needs far lower SIP than a 40-year-old for the same corpus.","Starting late gives the same result at the same SIP."),
   ("Retirement age assumptions","Retiring earlier needs a bigger corpus because savings must last more years with fewer years of accumulation.","A person retiring at 50 needs a larger corpus than at 60.","Retiring earlier lowers the corpus needed.")]),
 dict(n=11, title="Tax and estate planning", w=10,
  overview="Tax shapes returns; succession shapes legacy. This unit covers income tax basics, capital gains, deductions, wills, trusts and nomination.",
  focus=["Capital gains and deductions.", "Old versus new tax regime.", "Wills, nomination, trusts and HUF."],
  facts=[("Residential status","Tax liability in India depends on residential status — resident, non-resident or not ordinarily resident — which decides what income is taxable here.","A person who spends more than 182 days in India in a year is generally a resident.","Residential status depends only on citizenship."),
   ("Heads of income","Income is classified under five heads: salary, house property, business or profession, capital gains and other sources.","Rent from a flat and interest on a deposit fall under different heads.","All income is taxed under one head."),
   ("Capital gains","Capital gains are profits on the sale of capital assets, classified as short-term or long-term based on the holding period of the asset.","An investor sells shares for more than she paid.","Capital gains arise only from selling property."),
   ("Section 80C","Section 80C allows deductions up to a ceiling for specified investments and expenses under the old tax regime, such as PPF, ELSS and life insurance premium.","An investor claims a deduction for ELSS investment.","Section 80C is available under both regimes always."),
   ("New versus old regime","Taxpayers can choose between the default new regime with lower slab rates and few deductions, and the old regime with higher rates and many deductions.","A client compares tax payable under both regimes before choosing.","The old regime has no deductions."),
   ("Tax-loss harvesting","Tax-loss harvesting means selling investments at a loss to set off against gains, reducing the tax payable.","A client books a loss in one stock to offset a gain in another.","Tax-loss harvesting increases tax payable."),
   ("Set-off and carry forward","Capital losses can be set off against capital gains and carried forward for eight years, subject to conditions.","A loss this year is used to reduce gains next year.","Losses can never be carried forward."),
   ("TDS","Tax deducted at source is tax withheld by the payer on specified payments such as salary and interest, and credited to the payee's tax account.","A bank deducts tax on fixed deposit interest above the limit.","TDS is paid by the receiver in cash at year end."),
   ("Advance tax","Advance tax is paid in instalments during the year by taxpayers whose liability exceeds a threshold.","A trader pays tax quarterly instead of at year end.","Advance tax is paid only after filing the return."),
   ("Will","A will is a legal document by which a person decides how her property is to be distributed after death, and it takes effect only on death.","An investor states which heirs get which assets.","A will takes effect immediately on signing."),
   ("Intestate succession","When a person dies without a will, the property passes according to the succession laws applicable to the person's religion.","A man dies with no will and his assets pass as per the law.","Without a will, the government takes all property."),
   ("Probate","Probate is the court's certificate that proves a will is genuine and authorises the executor to administer the estate.","An executor obtains court proof before dealing with the assets.","Probate is the process of writing a will."),
   ("Nominee versus legal heir","A nominee is only a custodian who receives the asset on death and must hand it to the legal heirs; she is not necessarily the owner.","A nominee receives proceeds but must pass them on as per the will.","A nominee becomes the sole owner of the asset."),
   ("Trust","A trust holds assets for beneficiaries under a trustee's control, and is used for succession, protection and management of wealth.","A parent places assets under a trustee to benefit a child later.","A trust has no beneficiaries."),
   ("HUF","A Hindu Undivided Family is a separate taxable entity consisting of family members from a common ancestor, which can hold assets and file its own return.","A family unit with its own PAN and tax return.","An HUF is a company."),
   ("Gift tax rules","Gifts received from specified relatives are exempt from tax, while gifts above a threshold from others can be taxed as income of the receiver.","A son receives money from his father with no tax.","Gifts from relatives are taxed at 30%."),
   ("Power of attorney","A power of attorney authorises another person to act for the principal in specified matters, and ends on the principal's death.","An elderly client authorises her son to handle bank formalities.","A power of attorney continues after the principal's death."),
   ("Clubbing of income","Income earned from assets gifted to a spouse or minor child is generally clubbed with the giver's income for tax.","A husband gifts money to his wife who invests it, and the income is added to his.","Income of a minor child is always taxed separately.")]),
 dict(n=12, title="Regulatory environment and ethical issues", w=8,
  overview="SEBI's investment adviser regulations, the fiduciary duty and the code of conduct for advisers. Learn the exact rules.",
  focus=["Who needs registration.", "Fee limits and segregation.", "Risk profiling, suitability and records."],
  visuals=[("table", "Adviser regulation snapshot", [["Topic", "Rule"], ["Registration", "Mandatory for anyone giving investment advice for consideration"], ["Fees", "Fixed fee or % of AUA, not both, within SEBI caps"], ["Distribution", "Advisory and distribution must be segregated"], ["Records", "Maintained for at least five years"], ["Risk profiling", "Mandatory, with suitability documented"]], [140, 330])],
  facts=[("SEBI (Investment Advisers) Regulations","These regulations require anyone providing investment advice for a fee to be registered with SEBI and to follow conduct rules.","A person charging a fee for investment advice must hold the regulator's registration.","Anyone can give paid investment advice without registration."),
   ("Fee modes","An adviser may charge a fixed fee or a fee based on assets under advice, but not both for the same client, and within the limits prescribed by SEBI.","An adviser charges a flat annual fee rather than a percentage.","Advisers may charge both fixed fee and percentage at the same time."),
   ("Fee cap","SEBI has capped fees: up to ₹1.51 lakh per family per annum in fixed fee mode, or up to 2.5% of assets under advice per annum in AUA mode.","A fixed fee cannot exceed the prescribed limit per family.","SEBI places no limit on advisory fees."),
   ("Segregation of advisory and distribution","Advisory and distribution must be kept separate: an individual adviser cannot do both for the same client, and non-individual advisers need separate arrangements.","An adviser cannot earn commissions on the products sold to her advisory client.","An adviser may sell commission-based products to her advisory clients."),
   ("Risk profiling","Advisers must profile every client's risk before giving advice and document it, to ensure suitability.","An adviser uses a questionnaire to determine the client's risk tolerance.","Risk profiling is optional for advisers."),
   ("Suitability","Advice must be suitable for the client's risk profile, goals, horizon and financial position, and the reasons must be recorded.","An adviser recommends a safe product to an elderly client with low risk tolerance.","Advice can ignore the client's risk profile."),
   ("Client agreement","An adviser must enter into a written agreement with each client stating fees, services, and the rights and obligations of both.","A client signs a document describing the services and fees.","An adviser can provide services with no written agreement."),
   ("Disclosure of conflicts","An adviser must disclose any conflict of interest, such as holdings in recommended securities or relationships with product providers.","An adviser tells the client that she owns the recommended security.","Conflicts need not be disclosed."),
   ("Record keeping","An adviser must keep records of advice, risk profile, communications and fees for at least five years.","An adviser retains the client's risk profile and recommendations on file.","Records need to be kept for only one month."),
   ("Qualification and certification","An individual adviser needs prescribed qualifications and the NISM certification, and must meet minimum experience and net worth norms.","A person with the right degree and NISM certificate applies for registration.","Certification is not required for registration."),
   ("Principal officer and compliance","A non-individual adviser must appoint a principal officer with prescribed qualifications and a compliance officer to ensure compliance.","A firm appoints a certified principal officer.","Firms need not appoint any compliance officer."),
   ("Advertisement code","Advertisements by advisers must be fair, not misleading, and must not promise assured returns or guarantee performance.","An adviser's brochure must not claim guaranteed returns.","Advisers may promise guaranteed returns."),
   ("Confidentiality","An adviser must keep client information confidential and use it only for the advisory purpose, unless required by law.","An adviser does not share a client's holdings with anyone else.","An adviser may sell client data to product companies."),
   ("Code of conduct","The code of conduct for advisers includes honesty, diligence, care, transparency, avoidance of conflicts and compliance with the law.","An adviser acts honestly and in the client's best interest.","The code allows misleading statements about returns."),
   ("Grievance redressal","Advisers must have a mechanism to address client complaints, and clients can approach SEBI's complaint system and online dispute resolution if unsatisfied.","A client files a complaint on the regulator's portal after the adviser does not respond.","Clients have no route for complaints against advisers."),
   ("Annual audit","Registered advisers must undergo an annual compliance audit and submit reports as required.","A firm gets its compliance reviewed every year.","Advisers are never audited."),
   ("Prohibition of guaranteed returns","No intermediary may promise or guarantee returns on market-linked products; doing so is a violation.","A representative says, 'You will definitely get 15% every year.'","Intermediaries may guarantee returns if the client is wealthy.")]),
])
